import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"咖啡厅服务员求职邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/08-cafe-waiter-job-application.md","filePath":"zh/more/maltese/practice/emails/08-cafe-waiter-job-application.md"}'),e={name:"zh/more/maltese/practice/emails/08-cafe-waiter-job-application.md"},o=r('<h1 id="咖啡厅服务员求职邮件" tabindex="-1">咖啡厅服务员求职邮件 <a class="header-anchor" href="#咖啡厅服务员求职邮件" aria-label="Permalink to &quot;咖啡厅服务员求职邮件&quot;">​</a></h1><p><strong>场景：</strong> 申请人写信给咖啡厅经理，申请咖啡厅的服务员职位。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:info@kafetterija.com" target="_blank" rel="noreferrer">info@kafetterija.com</a><strong>Mingħand（发件人 From）：</strong> [isem]@email.com <strong>Data（日期）：</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Applikazzjoni ta&#39; xogħol ta&#39; wejter</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@kafetterija.com" target="_blank" rel="noreferrer">info@kafetterija.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; wejter</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; wejter fil-kafetterija tagħkom.</p><p>Għandi esperjenza ta&#39; sentejn fis-servizz tal-klijenti.</p><p>Nista&#39; naqdi lill-klijenti b&#39;mod edukat u bil-ħeffa.</p><p>Nitgħallem malajr u nifhem il-bżonnijiet tal-klijenti.</p><p>Jien persuna ta&#39; ħbiberija u nħobb naħdem man-nies.</p><p>Nista&#39; naħdem filgħodu u filgħaxija.</p><p>Nispera li ningħaqad mat-tim tagħkom.</p><p>Grazzi talli ħadtu ħsieb l-applikazzjoni tiegħi.</p><p>Nistenna bil-ħerqa li nisma&#39; mingħandkom.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@kafetterija.com" target="_blank" rel="noreferrer">info@kafetterija.com</a></p><p><strong>整句：</strong> 收件人（To）：info@kafetterija.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:info@kafetterija.com" target="_blank" rel="noreferrer">info@kafetterija.com</a></td><td>邮箱地址</td><td>咖啡厅的招聘邮箱（示例）</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>整句：</strong> 发件人（From）：[你的名字]@email.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td>[isem]@email.com</td><td>邮箱地址</td><td>你的邮箱占位，请替换为真实邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 15 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>15</td><td>十五</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; wejter</p><p><strong>整句：</strong> 主题：服务员职位申请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Applikazzjoni</td><td>申请</td><td>阴性名词，借词 application</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>xogħol</td><td>工作；职位</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>wejter</td><td>服务员</td><td>阳性名词，借词 waiter</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>整句：</strong> 亲爱的先生 / 女士：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形式</td></tr><tr><td>Sinjur</td><td>先生</td><td>阳性名词</td></tr><tr><td>/</td><td>或</td><td>表示二选一</td></tr><tr><td>Sinjura</td><td>女士</td><td>阴性名词</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; wejter fil-kafetterija tagħkom.</p><p><strong>整句：</strong> 我写信是为了申请你们咖啡厅的服务员职位。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在（进行时标记）</td><td>与动词连用表示正在做某事</td></tr><tr><td>nikteb</td><td>我写</td><td>第一人称单数现在时</td></tr><tr><td>biex</td><td>为了</td><td>引出目的状语</td></tr><tr><td>napplika</td><td>我申请</td><td>第一人称单数形式，借词 apply</td></tr><tr><td>għall-impjieg</td><td>申请职位</td><td><code>għal</code> + <code>l-impjieg</code> 缩合</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属/类别连接词</td></tr><tr><td>wejter</td><td>服务员</td><td>阳性名词，借词 waiter</td></tr><tr><td>fil-kafetterija</td><td>在咖啡厅</td><td><code>f&#39;</code> + <code>il-kafetterija</code> 缩合</td></tr><tr><td>tagħkom</td><td>你们的</td><td>复数所有格代词</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi esperjenza ta&#39; sentejn fis-servizz tal-klijenti.</p><p><strong>整句：</strong> 我有两年的顾客服务经验。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>esperjenza</td><td>经验</td><td>阴性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>sentejn</td><td>两年</td><td><code>sentejn</code>“两年”的固定形式</td></tr><tr><td>fis-servizz</td><td>在服务方面</td><td><code>f&#39;</code> + <code>is-servizz</code> 缩合</td></tr><tr><td>tal-klijenti</td><td>顾客的</td><td><code>ta&#39;</code> + <code>il-klijenti</code>（复数）缩合</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; naqdi lill-klijenti b&#39;mod edukat u bil-ħeffa.</p><p><strong>整句：</strong> 我能礼貌而快速地服务顾客。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数形式</td></tr><tr><td>naqdi</td><td>我服务</td><td>第一人称单数现在时</td></tr><tr><td>lill-klijenti</td><td>给顾客们</td><td><code>li</code> + <code>l-klijenti</code> 缩合，引出宾语</td></tr><tr><td>b&#39;mod</td><td>以……方式</td><td><code>b&#39;</code>“以” + <code>mod</code>“方式”</td></tr><tr><td>edukat</td><td>有礼貌的</td><td>形容词</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>bil-ħeffa</td><td>快速地</td><td><code>b&#39;</code> + <code>il-ħeffa</code>“速度”缩合</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Nitgħallem malajr u nifhem il-bżonnijiet tal-klijenti.</p><p><strong>整句：</strong> 我学得快，并且理解顾客的需求。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nitgħallem</td><td>我学习</td><td>第一人称单数形式</td></tr><tr><td>malajr</td><td>快地</td><td>副词</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>nifhem</td><td>我理解</td><td>第一人称单数现在时</td></tr><tr><td>il-bżonnijiet</td><td>需求</td><td><code>bżonn</code>“需要”的复数形式</td></tr><tr><td>tal-klijenti</td><td>顾客的</td><td><code>ta&#39;</code> + <code>il-klijenti</code> 缩合</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Jien persuna ta&#39; ħbiberija u nħobb naħdem man-nies.</p><p><strong>整句：</strong> 我是一个友善的人，喜欢和人们打交道。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>第一人称单数代词</td></tr><tr><td>persuna</td><td>人</td><td>阴性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>ħbiberija</td><td>友善；友好</td><td>阴性名词</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>nħobb</td><td>我喜欢</td><td>第一人称单数形式</td></tr><tr><td>naħdem</td><td>我工作</td><td>第一人称单数现在时</td></tr><tr><td>man-nies</td><td>和人们</td><td><code>ma&#39;</code>“和” + <code>in-nies</code>“人们”缩合</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; naħdem filgħodu u filgħaxija.</p><p><strong>整句：</strong> 我可以上午和晚上都上班。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数形式</td></tr><tr><td>naħdem</td><td>我工作</td><td>第一人称单数现在时</td></tr><tr><td>filgħodu</td><td>在上午</td><td>时间表达</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li ningħaqad mat-tim tagħkom.</p><p><strong>整句：</strong> 我希望加入你们的团队。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>ningħaqad</td><td>我加入</td><td>第一人称单数形式</td></tr><tr><td>mat-tim</td><td>和团队</td><td><code>ma&#39;</code> + <code>it-tim</code> 缩合</td></tr><tr><td>tagħkom</td><td>你们的</td><td>复数所有格代词</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli ħadtu ħsieb l-applikazzjoni tiegħi.</p><p><strong>整句：</strong> 感谢你们考虑我的申请。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>talli</td><td>因为（你们）……</td><td>引出原因的书面表达</td></tr><tr><td>ħadtu</td><td>你们拿了</td><td><code>ħa</code>“拿”的第三人称复数过去时</td></tr><tr><td>ħsieb</td><td>考虑；心思</td><td><code>ħadtu ħsieb</code> 固定搭配“你们考虑了”</td></tr><tr><td>l-applikazzjoni</td><td>申请</td><td>阴性名词，带定冠词</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Nistenna bil-ħerqa li nisma&#39; mingħandkom.</p><p><strong>整句：</strong> 我热切期待收到你们的回复。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nistenna</td><td>我等待；我期待</td><td>第一人称单数形式</td></tr><tr><td>bil-ħerqa</td><td>热切地；期待地</td><td>固定副词短语</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>nisma&#39;</td><td>我听到；收到消息</td><td>第一人称单数形式</td></tr><tr><td>mingħandkom</td><td>从你们那里</td><td><code>mingħand</code> + <code>-kom</code>“你们”</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>整句：</strong> 此致敬意，[你的名字]（正式邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Ismek</td><td>你的名字</td><td><code>isem</code>“名字” + <code>-ek</code>“你的”；请替换为真实姓名</td></tr></tbody></table>',61),i=[o];function n(l,h,s,p,b,c){return d(),a("div",null,i)}const u=t(e,[["render",n]]);export{m as __pageData,u as default};
